import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-recommendation',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header" style="background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);">
      <div class="container">
        <span class="material-icons" style="font-size:3rem;margin-bottom:0.5rem;">psychology</span>
        <h1>Gợi Ý Thông Minh</h1>
        <p>Trả lời vài câu hỏi để nhận gợi ý địa điểm phù hợp với bạn</p>
      </div>
    </div>
    <section class="section">
      <div class="container">
        <div class="rec-layout">
          <div class="rec-form">
            <h3><span class="material-icons">quiz</span> Trả lời câu hỏi</h3>

            <div class="form-group">
              <label>Bạn muốn đi khu vực nào?</label>
              <div class="checkbox-group">
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.north"> Miền Bắc</label>
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.central"> Miền Trung</label>
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.south"> Miền Nam</label>
              </div>
            </div>

            <div class="form-group">
              <label>Loại hình du lịch?</label>
              <div class="checkbox-group">
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.beach"> Biển & Đảo</label>
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.mountain"> Núi & Rừng</label>
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.historic"> Di tích & Lịch sử</label>
                <label class="checkbox-item"><input type="checkbox" [(ngModel)]="preferences.nature"> Thiên nhiên</label>
              </div>
            </div>

            <div class="form-group">
              <label>Ngân sách của bạn?</label>
              <div class="radio-group">
                <label class="radio-item"><input type="radio" [(ngModel)]="preferences.budget" value="low"> Tiết kiệm</label>
                <label class="radio-item"><input type="radio" [(ngModel)]="preferences.budget" value="medium"> Trung bình</label>
                <label class="radio-item"><input type="radio" [(ngModel)]="preferences.budget" value="high"> Cao cấp</label>
              </div>
            </div>

            <button class="btn btn-primary btn-lg" style="width:100%;" (click)="getRecommendations()" [disabled]="loading">
              <span class="material-icons">auto_awesome</span>
              {{ loading ? 'Đang gợi ý...' : 'Gợi ý cho tôi' }}
            </button>
          </div>

          <div class="rec-results">
            <div *ngIf="!results && !loading" class="empty-state">
              <span class="material-icons">travel_explore</span>
              <h3>Chọn sở thích của bạn</h3>
              <p>Chúng tôi sẽ gợi ý những địa điểm phù hợp nhất</p>
            </div>

            <div *ngIf="loading" class="loading-spinner"><div class="spinner"></div></div>

            <div *ngIf="results?.recommendations?.length" class="results-list">
              <h3>Kết quả gợi ý ({{ results.recommendations.length }} địa điểm)</h3>
              <p class="algo-note">Algorithm: {{ results.algorithm }}</p>
              <div *ngFor="let r of results.recommendations" class="result-card card">
                <img [src]="r.images?.[0]?.url || 'https://picsum.photos/seed/' + r.slug + '/200/150'" [alt]="r.name">
                <div class="result-info">
                  <h4>{{ r.name }}</h4>
                  <p class="location"><span class="material-icons">location_on</span> {{ r.province?.name }}</p>
                  <div class="score-bar">
                    <div class="score-fill" [style.width.%]="r.recommendationScore"></div>
                  </div>
                  <p class="score-text">Match: {{ r.recommendationScore | number:'1.0-0' }}%</p>
                  <div class="reasons">
                    <span class="badge badge-primary" *ngFor="let reason of r.matchReasons.slice(0,2)">{{ reason }}</span>
                  </div>
                </div>
                <a [routerLink]="['/destinations', r.slug]" class="btn btn-sm btn-outline">Xem chi tiết</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .rec-layout { display: grid; grid-template-columns: 380px 1fr; gap: 2rem; @media(max-width:768px){grid-template-columns:1fr;} }
    .rec-form { background: white; border-radius: var(--border-radius); padding: 2rem; box-shadow: var(--shadow); position: sticky; top: 90px; h3 { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 1.5rem; .material-icons { color: var(--primary); } } }
    .form-group { margin-bottom: 1.5rem; label { font-weight: 600; margin-bottom: 0.5rem; display: block; } }
    .checkbox-group { display: flex; flex-direction: column; gap: 0.5rem; }
    .checkbox-item, .radio-item { display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem; border-radius: 6px; cursor: pointer; &:hover { background: var(--light); } input { width: 18px; height: 18px; } }
    .radio-group { display: flex; gap: 1rem; flex-wrap: wrap; }
    .results-list { h3 { margin-bottom: 0.25rem; } }
    .algo-note { color: var(--gray); font-size: 0.875rem; margin-bottom: 1.5rem; }
    .result-card { display: flex; gap: 1rem; padding: 1rem; margin-bottom: 1rem; align-items: center; img { width: 120px; height: 90px; object-fit: cover; border-radius: 8px; flex-shrink: 0; } }
    .result-info { flex: 1; h4 { margin-bottom: 0.25rem; font-size: 1rem; } }
    .location { display: flex; align-items: center; gap: 0.25rem; color: var(--gray); font-size: 0.875rem; margin-bottom: 0.5rem; .material-icons { font-size: 1rem; } }
    .score-bar { height: 6px; background: #e2e8f0; border-radius: 3px; margin-bottom: 0.25rem; }
    .score-fill { height: 100%; background: linear-gradient(90deg, var(--primary), #667eea); border-radius: 3px; }
    .score-text { font-size: 0.8125rem; font-weight: 600; color: var(--primary); margin-bottom: 0.25rem; }
    .reasons { display: flex; gap: 0.25rem; flex-wrap: wrap; }
  `]
})
export class RecommendationComponent implements OnInit {
  loading = false;
  results: any = null;
  preferences: any = {};

  constructor(private api: ApiService, public auth: AuthService) {}

  ngOnInit() {}

  getRecommendations() {
    this.loading = true;
    const prefs: any = {};
    const regions: string[] = [];
    const categories: string[] = [];

    if (this.preferences.north) regions.push('NORTH');
    if (this.preferences.central) regions.push('CENTRAL');
    if (this.preferences.south) regions.push('SOUTH');
    if (this.preferences.beach) categories.push('bien');
    if (this.preferences.mountain) categories.push('nui-rung');
    if (this.preferences.historic) categories.push('di-tich');
    if (this.preferences.nature) categories.push('thien-nhien');

    if (regions.length) prefs.regions = regions;
    if (categories.length) prefs.categories = categories;
    if (this.preferences.budget) prefs.budget = this.preferences.budget;

    this.api.getRecommendations(prefs).subscribe({
      next: (res) => { this.results = res; this.loading = false; },
      error: () => { this.loading = false; }
    });
  }
}
